async function fixedWindowRateLimit(ip) {
  const windowTime = Math.floor(Date.now() / 60000); // 1-minute window key
  const key = `ratelimit:${ip}:${windowTime}`;

  const requests = await redis.incr(key);
  if (requests === 1) {
    await redis.expire(key, 60); // Set 60s TTL on initial key creation
  }

  if (requests > 100) {
    return { allowed: false, remaining: 0 }; // Exceeded limit!
  }
  return { allowed: true, remaining: 100 - requests };
}
